            <li data-assurance="cancel">Cancel anytime</li>
            <li data-assurance="stack">Works with your stack</li>
          </ul>
        </div>
        <div class="decision-board" aria-label="Example decision board">
          <p class="board-label">Launch decision · Today</p>
          <h2>Which onboarding should ship?</h2>
          <div class="board-row">
            <span class="avatar" aria-hidden="true">AM</span>
            <div><strong>Aria</strong><small>Shared customer evidence</small></div>
            <span class="status">Ready</span>
          </div>
          <div class="board-row">
            <span class="avatar avatar-alt" aria-hidden="true">JK</span>
            <div><strong>Jules</strong><small>Confirmed engineering scope</small></div>
            <span class="status">Ready</span>
          </div>
