      <section id="proof" class="proof-section" aria-labelledby="proof-title">
        <p class="section-label">Proof without another meeting</p>
        <h2 id="proof-title">One decision trail everyone can follow.</h2>
        <div class="proof-grid">
          <article class="proof-card">
            <strong>4.8h</strong>
